796	    BABYLON.Effect.ShadersStore["modelingGridVertexShader"] = `
797	      precision highp float;
798	      attribute vec3 position;
799	      uniform mat4 worldViewProjection;
800	      uniform float uScale;
801	      uniform vec2 uOffset;
802	      // Position dans le plan du motif, relative à l'ancre de la grille (cf. recenterGridGround).
803	      // Le plan est un carré unité recentré sur la cible et mis à l'échelle du rayon caméra à
804	      // chaque frame : ses sommets restent donc à une distance de l'ordre du champ visible, et
805	      // l'interpolation float32 de cette varying garde une précision proportionnelle au zoom.
806	      // Avec un plan fixe géant (sommets à des dizaines de mètres), l'erreur d'interpolation
807	      // (~taille x 6e-8) dépassait la taille d'un pixel, puis du champ entier au zoom extrême :
808	      // fwidth() devenait bruité, d'où des bandes, puis une grille vide. uOffset (cible - ancre)
809	      // est calculé côté CPU en double précision et reste petit.
810	      varying vec2 vGridPos;
811	      varying vec2 vUnitPos;
812	      void main(void) {
813	        vGridPos = position.xz * uScale + uOffset;
814	        vUnitPos = position.xz;
815	        gl_Position = worldViewProjection * vec4(position, 1.0);
816	      }
817	    `;
818	    BABYLON.Effect.ShadersStore["modelingGridFragmentShader"] = `
819	      precision highp float;
820	      varying vec2 vGridPos;
821	      varying vec2 vUnitPos;
822	      uniform vec3 uMinorColor;
823	      uniform vec3 uMajorColor;
824	      uniform float uMinorAlpha;
825	      uniform float uMajorAlpha;
826	      uniform float uMinPx;
827	      uniform float uMinExponent;
828	
829	      // Distance (en pixels) au trait le plus proche d'un quadrillage de pas spacing, à partir
830	      // d'une position ET d'une dérivée déjà calculées — jamais de fwidth() ici : spacing
831	      // varie de façon DISCONTINUE d'un pixel à l'autre (cf. plus bas), et rappeler fwidth() sur
832	      // une expression qui en dépend (position / spacing) ferait comparer par différence finie
833	      // deux pixels voisins avec des pas différents pile à la frontière — le GPU y calculerait
834	      // n'importe quoi, masquant les traits par bandes entières à cet endroit précis de l'écran
835	      // (fixe, puisque lié à la distance caméra-sol, pas à la position qu'on regarde).
836	      float gridMask(vec2 worldXZ, vec2 worldDeriv, float spacing, float halfWidthPx) {
837	        vec2 coord = worldXZ / spacing;
838	        vec2 coordDeriv = worldDeriv / spacing;
839	        vec2 dist = abs(fract(coord + 0.5) - 0.5) / max(coordDeriv, vec2(1e-6));
840	        float d = min(dist.x, dist.y);
841	        return 1.0 - clamp(d / halfWidthPx, 0.0, 1.0);
842	      }
843	
844	      void main(void) {
845	        // Seul appel à fwidth() du shader, sur une grandeur continue (vGridPos) — tout le reste
846	        // s'en déduit par simple arithmétique (cf. gridMask ci-dessus).
847	        vec2 worldDeriv = fwidth(vGridPos);
848	        float worldPerPixel = max(max(worldDeriv.x, worldDeriv.y), 1e-12);
849	
850	        // Seuils, en pixels d'écart à l'écran entre deux traits d'une même famille : un trait fin
851	        // apparaît en fondu entre FINE_IN et FINE_FULL, puis s'éclaircit et s'épaissit jusqu'au
852	        // rendu « principal » entre MAIN_IN et MAIN_FULL.
853	        float fineIn = 0.6 * uMinPx;
854	        float fineFull = 1.4 * uMinPx;
855	        float mainIn = 5.0 * uMinPx;
856	        float mainFull = 12.0 * uMinPx;
857	
858	        // Familles de traits de pas 1·10^k et 2·10^k : 10^(k+1) ⊂ 2·10^k ⊂ 10^k, donc en zoomant un
859	        // carreau principal se divise d'abord en 5 (pas 2·10^k), puis en 10 (pas 10^k), et ces
860	        // traits fins deviennent à leur tour principaux — sans qu'aucun trait ne bouge. Chaque
861	        // famille a une intensité, une couleur et une épaisseur fonctions CONTINUES de son propre
862	        // écart à l'écran : aucune bascule brutale quand le pixel change d'échelle.
863	        // Plancher à uMinExponent : le plus fin des pas tracés ne descend jamais sous
864	        // 10^uMinExponent (limite de précision, cf. CPU).
865	        float baseExp = max(floor(log(fineIn * worldPerPixel) / log(10.0)), uMinExponent);
866	        vec3 color = uMinorColor;
867	        float alpha = 0.0;
868	        for (int e = 0; e <= 3; e++) {
869	          for (int m = 0; m < 2; m++) {
870	            float spacing = pow(10.0, baseExp + float(e)) * (m == 0 ? 1.0 : 2.0);
871	            float spacingPx = spacing / worldPerPixel;
872	            float visible = smoothstep(fineIn, fineFull, spacingPx);
873	            if (visible <= 0.0) continue;
874	            float major = smoothstep(mainIn, mainFull, spacingPx);
875	            float mask = gridMask(vGridPos, worldDeriv, spacing, mix(0.55, 0.95, major));
876	            float a = mask * visible * mix(uMinorAlpha, uMajorAlpha, major);
877	            if (a > alpha) {
878	              alpha = a;
879	              color = mix(uMinorColor, uMajorColor, major);
880	            }
881	          }
882	        }
883	
884	        // Fondu vers le bord du plan : sa limite ne se voit jamais, même en vue rasante.
885	        alpha *= 1.0 - smoothstep(0.6, 1.0, length(vUnitPos));
886	
887	        if (alpha < 0.004) discard;
888	        gl_FragColor = vec4(color, alpha);
889	      }
890	    `;
