.overlay {
  position: fixed;
  inset: 0;
  z-index: 5000;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
  overflow: hidden;
}

// Étape 1 : flou seul, sans aucune teinte — une simple loupe sur ce qu'il y a derrière.
.blurLayer {
  position: absolute;
  inset: 0;
  -webkit-backdrop-filter: blur(0px);
}

// Étape 2 : voile bleu opaque façon peinture/liquide, découpé en diagonale par le clip-path
// animé côté TSX (diagonalClipPath) plutôt qu'ici, pour interpoler sa forme frame par frame.
.veil {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(120% 140% at 100% 0%, rgba(60, 210, 255, 0.9), rgba(0, 60, 130, 0.97) 55%, rgba(0, 20, 55, 1) 100%);
}

.textBlock {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  text-align: center;
}

.brand {
  font-family: 'Ethnocentric', 'Orbitron', sans-serif;
  font-weight: 400;
  font-size: 22px;
  letter-spacing: 0.3em;
  color: #eafcff;
  text-shadow: 0 0 16px rgba(255, 255, 255, 0.6), 0 0 40px rgba(0, 240, 255, 0.5);
}

.spaceName {
  font-family: 'Orbitron', sans-serif;
  font-weight: 700;
  font-size: 34px;
  color: rgba(255, 255, 255, 0.92);
  text-shadow: 0 0 20px rgba(0, 240, 255, 0.6);
}

.scanline {
  position: absolute;
  left: 0;
  right: 0;
  bottom: -12px;
  height: 2px;
  background: linear-gradient(90deg, transparent, #ffffff, transparent);
  transform-origin: center;
}

