import React, { useEffect, useState, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import styles from './SpaceTransitionOverlay.module.scss';

/**
 * Rideau plein écran joué à chaque changement d'espace (Préparation / Prévisualisation /
 * Modélisation / Dev), en 4 étapes STRICTEMENT séquentielles (jamais mélangées) :
 *   1. blur    — flou de l'interface, sans aucune teinte de couleur.
 *   2. paint   — un voile bleu opaque « coule » en diagonale, du coin haut-droit vers le coin
 *                bas-gauche (façon peinture/liquide), par-dessus le flou déjà en place.
 *   3. text    — le texte apparaît une fois le voile plein écran ("APEX" en Ethnocentric, le nom
 *                de l'espace en Orbitron) ; c'est aussi à ce moment que le switch réel a lieu.
 *   4. fadeout — le voile disparaît en fondu et le flou se dissipe en même temps, révélant le
 *                nouvel espace.
 *
 * Piloté par l'événement `apex-space-transition` (voir Sidebar.tsx, seul émetteur) plutôt qu'un
 * state React partagé, pour rester cohérent avec le bus d'événements global du reste de l'app
 * (cf. CLAUDE.md).
 */

const BLUR_MS = 260;     // 1. montée du flou seul
const PAINT_MS = 380;    // 2. le voile bleu balaie l'écran en diagonale
const TEXT_MS = 420;     // 3. texte affiché, voile plein écran (switch réel ici)
const FADEOUT_MS = 420;  // 4. voile + flou disparaissent ensemble
const TOTAL_MS = BLUR_MS + PAINT_MS + TEXT_MS + FADEOUT_MS;

type Phase = 'blur' | 'paint' | 'text' | 'fadeout';

interface SpaceTransitionDetail {
  label: string;
  onCovered?: () => void;
}

// Triangle qui part du coin haut-droit (0% de couverture) et grossit vers le coin bas-gauche
// jusqu'à couvrir tout le rectangle : polygone à 4 points sur les bords haut/droit puis
// bas/gauche, chacun interpolé entre "juste le coin" et "le bord entier".
function diagonalClipPath(t: number): string {
  const p = Math.max(0, Math.min(1, t));
  // Bord haut : de l'angle (100,0) vers (0,0). Bord droit : de (100,0) vers (100,100).
  const topX = 100 - 100 * p;
  const rightY = 100 * p;
  // Bord bas puis gauche suivent avec un léger retard pour donner un sens d'écoulement, pas un
  // simple agrandissement centré.
  const flow = Math.max(0, Math.min(1, (p - 0.35) / 0.65));
  const bottomX = 100 - 100 * flow;
  const leftY = 100 * flow;
  return `polygon(100% 0%, ${topX}% 0%, 0% ${leftY}%, 0% 100%, ${bottomX}% 100%, 100% ${rightY}%)`;
}

export const SpaceTransitionOverlay: React.FC = () => {
  const [label, setLabel] = useState<string | null>(null);
  const [phase, setPhase] = useState<Phase>('blur');
  const timeoutsRef = useRef<number[]>([]);

  useEffect(() => {
    const clearTimeouts = () => {
      timeoutsRef.current.forEach((id) => window.clearTimeout(id));
      timeoutsRef.current = [];
    };

    const handleTransition = (e: Event) => {
      const detail = (e as CustomEvent<SpaceTransitionDetail>).detail;
      if (!detail?.label) return;

      clearTimeouts();
      setLabel(detail.label);
      setPhase('blur');

      timeoutsRef.current.push(
        window.setTimeout(() => setPhase('paint'), BLUR_MS),
        window.setTimeout(() => {
          // Le contenu change une fois le voile plein écran, jamais visible.
          detail.onCovered?.();
          setPhase('text');
        }, BLUR_MS + PAINT_MS),
        window.setTimeout(() => setPhase('fadeout'), BLUR_MS + PAINT_MS + TEXT_MS),
        window.setTimeout(() => setLabel(null), TOTAL_MS),
      );
    };

    window.addEventListener('apex-space-transition', handleTransition);
    return () => {
      window.removeEventListener('apex-space-transition', handleTransition);
      clearTimeouts();
    };
  }, []);

  return (
    <AnimatePresence>
      {label && (
        <div className={styles.overlay}>
          {/* Flou seul, sans teinte — reste actif de 'blur' à juste avant 'fadeout'. */}
          <motion.div
            className={styles.blurLayer}
            initial={{ backdropFilter: 'blur(0px)' }}
            animate={{ backdropFilter: phase === 'fadeout' ? 'blur(0px)' : 'blur(18px)' }}
            transition={{ duration: (phase === 'fadeout' ? FADEOUT_MS : BLUR_MS) / 1000, ease: [0.4, 0, 0.2, 1] }}
          />

          {/* Voile bleu opaque, façon coulée diagonale. */}
          <motion.div
            className={styles.veil}
            initial={{ clipPath: diagonalClipPath(0), opacity: 1 }}
            animate={
              phase === 'blur'
                ? { clipPath: diagonalClipPath(0), opacity: 1 }
                : phase === 'fadeout'
                ? { clipPath: diagonalClipPath(1), opacity: 0 }
                : { clipPath: diagonalClipPath(1), opacity: 1 }
            }
            transition={
              phase === 'paint'
